SELECT
transaction_id, transaction_key, transaction_type, amount, balance_after,
counterparty_name, counterparty_account_number, memo, transaction_at,
transfer_id, account_id, created_at, updated_at
FROM bank_transaction
WHERE account_id = #{accountId}

    AND transaction_id < #{beforeTransactionId}

ORDER BY transaction_id DESC
LIMIT #{size}

